jsonTools.init:
function init(eli) {
  var TPL_STORE = "bd_templates";
  var _state = {
    selectedId: null,
    selectedRow: null,        // raw IDB row (post-decompress)
    sourcePkg: null,          // source pkg string (decompressed body)
    sourceParts: null,        // { styles, numbering, document }
    targetPkg: null,          // target pkg string (post-load)
    targetParts: null,        // { styles, numbering, document }
  };

  function _toast(msg, type) { if (typeof showToast === "function") showToast(msg, type || "info"); }
  function _esc(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
  }

  // ─── IDB helpers ─────────────────────────────────────────────────────
  // bd_templates rows may be pako-compressed (rec._z===1, rec.content is
  // Uint8Array). Decompress in place via window.pako.
  function _decompressRowIfNeeded(rec) {
    if (!rec || !rec._z) return rec;
    if (typeof window.pako === "undefined" || typeof window.pako.inflate !== "function") {
      throw new Error("pako not loaded — add https://cdn.jsdelivr.net/npm/pako@2.1.0/dist/pako.min.js to Script Lab Libraries");
    }
    var td = new TextDecoder("utf-8");
    var utf8 = window.pako.inflate(rec.content);
    var out = {};
    for (var k in rec) if (rec.hasOwnProperty(k)) out[k] = rec[k];
    out.content = td.decode(utf8);
    out._wasCompressed = true;
    delete out._z;
    return out;
  }

  // Fetch and decompress a template. Returns { row, contentString }.
  function _fetchTemplate(id) {
    return eli.storage.get(TPL_STORE, id).then(function (rec) {
      if (!rec) throw new Error("Template not found: " + id);
      var decompressed = _decompressRowIfNeeded(rec);
      return { row: decompressed, contentString: decompressed.content };
    });
  }

  function _listTemplates() {
    return eli.storage.getAll(TPL_STORE).then(function (rows) {
      // Skip kernel-reserved underscore rows.
      return (rows || []).filter(function (r) {
        return r && r.id && String(r.id).charAt(0) !== "_";
      }).sort(function (a, b) {
        return (b.modifiedAt || 0) - (a.modifiedAt || 0);
      });
    });
  }

  // ─── pkg part extraction (shared with strategies) ────────────────────
  function _extractPkgPart(pkgString, name) {
    if (!pkgString || typeof pkgString !== "string") return "";
    var re = new RegExp('<pkg:part[^>]+name="\\/word\\/' + name + '\\.xml"[^>]*>[\\s\\S]*?<\\/pkg:part>');
    var m = pkgString.match(re);
    return m ? m[0] : "";
  }
  function _parseAllParts(pkgString) {
    return {
      styles: _extractPkgPart(pkgString, "styles"),
      numbering: _extractPkgPart(pkgString, "numbering"),
      document: _extractPkgPart(pkgString, "document"),
    };
  }

  // ─── XML inspectors ──────────────────────────────────────────────────
  // Returns array of { styleId, name, numId, ilvl, bold, italic, jc, sz }
  // for every custom style. numId is null if no style-linked numbering.
  function _inspectCustomStyles(stylesXml) {
    var out = [];
    if (!stylesXml) return out;
    var styleRe = /<w:style\b([^>]*)>([\s\S]*?)<\/w:style>/g, sm;
    while ((sm = styleRe.exec(stylesXml))) {
      var attrs = sm[1], inner = sm[2];
      if (attrs.indexOf('w:customStyle="1"') === -1) continue;
      var idM = attrs.match(/w:styleId="([^"]+)"/);
      if (!idM) continue;
      var nameM = inner.match(/<w:name\s+w:val="([^"]+)"\s*\/>/);
      var pPrM = inner.match(/<w:pPr>([\s\S]*?)<\/w:pPr>/);
      var rPrM = inner.match(/<w:rPr>([\s\S]*?)<\/w:rPr>/);
      var pPrI = pPrM ? pPrM[1] : "";
      var rPrI = rPrM ? rPrM[1] : "";
      var numPrM = pPrI.match(/<w:numPr>([\s\S]*?)<\/w:numPr>/);
      var numId = numPrM && (numPrM[1].match(/<w:numId\s+w:val="(\d+)"/) || [])[1] || null;
      var ilvl = numPrM && (numPrM[1].match(/<w:ilvl\s+w:val="(\d+)"/) || [])[1] || null;
      var jc = (pPrI.match(/<w:jc\s+w:val="([^"]+)"/) || [])[1] || null;
      var bold = /<w:b(?:\s+w:val="(?:true|1)")?\s*\/>/.test(rPrI) && !/<w:b\s+w:val="(?:false|0)"\s*\/>/.test(rPrI);
      var italic = /<w:i(?:\s+w:val="(?:true|1)")?\s*\/>/.test(rPrI) && !/<w:i\s+w:val="(?:false|0)"\s*\/>/.test(rPrI);
      var sz = (rPrI.match(/<w:sz\s+w:val="(\d+)"/) || [])[1] || null;
      out.push({
        styleId: idM[1], name: nameM ? nameM[1] : idM[1],
        numId: numId, ilvl: ilvl, jc: jc, bold: bold, italic: italic, sz: sz,
      });
    }
    return out;
  }

  // Returns array of { numId, abstractNumId, levels: [{ilvl, lvlText, linkedStyle}] }
  function _inspectNumbering(numberingXml) {
    var out = [];
    if (!numberingXml) return out;
    var numRe = /<w:num\s+w:numId="(\d+)"[^>]*>([\s\S]*?)<\/w:num>/g, nm;
    var nums = [];
    while ((nm = numRe.exec(numberingXml))) {
      var absId = (nm[2].match(/<w:abstractNumId\s+w:val="(\d+)"/) || [])[1] || null;
      nums.push({ numId: nm[1], abstractNumId: absId });
    }
    nums.forEach(function (n) {
      var levels = [];
      if (n.abstractNumId != null) {
        var absRe = new RegExp('<w:abstractNum\\s+w:abstractNumId="' + n.abstractNumId + '"[^>]*>([\\s\\S]*?)<\\/w:abstractNum>');
        var absM = numberingXml.match(absRe);
        if (absM) {
          var lvlRe = /<w:lvl\b([^>]*)>([\s\S]*?)<\/w:lvl>/g, lm;
          while ((lm = lvlRe.exec(absM[1]))) {
            var ilvlM = lm[1].match(/w:ilvl="(\d+)"/);
            if (!ilvlM) continue;
            var fmt = (lm[2].match(/<w:lvlText\s+w:val="([^"]+)"/) || [])[1] || null;
            var linked = (lm[2].match(/<w:pStyle\s+w:val="([^"]+)"\s*\/>/) || [])[1] || null;
            levels.push({ ilvl: ilvlM[1], lvlText: fmt, linkedStyle: linked });
          }
        }
      }
      out.push({ numId: n.numId, abstractNumId: n.abstractNumId, levels: levels });
    });
    return out;
  }

  // Returns array of first N Colgate*-styled paragraphs with their numPr + text.
  function _inspectParagraphs(documentXml, limit) {
    var out = [];
    if (!documentXml) return out;
    var paragraphs = documentXml.match(/<w:p\b[^>]*>[\s\S]*?<\/w:p>/g) || [];
    var shown = 0;
    for (var i = 0; i < paragraphs.length && shown < (limit || 30); i++) {
      var p = paragraphs[i];
      var stM = p.match(/<w:pStyle\s+w:val="(Colgate[^"]+)"/);
      if (!stM) continue;
      var nM = p.match(/<w:numPr>([\s\S]*?)<\/w:numPr>/);
      var nid = nM && (nM[1].match(/<w:numId\s+w:val="(\d+)"/) || [])[1] || null;
      var ilv = nM && (nM[1].match(/<w:ilvl\s+w:val="(\d+)"/) || [])[1] || null;
      var txt = (p.match(/<w:t[^>]*>([^<]+)<\/w:t>/) || [])[1] || "";
      out.push({ index: i, style: stM[1], numId: nid, ilvl: ilv, text: txt.substring(0, 60) });
      shown++;
    }
    return out;
  }

  // ─── target pkg fetch (live doc) ─────────────────────────────────────
  function _fetchTargetPkg() {
    return eli.host.runRaw("trl:fetch_target", function (ctx) {
      var req = ctx.document.body.getOoxml();
      return ctx.sync().then(function () { return req.value; });
    });
  }

  // ─── strategies ──────────────────────────────────────────────────────
  // Strategy A — pre-insert inline numPr bake with abstractNum reverse-lookup.
  // Transforms a source pkg string and returns the new pkg string. Caller
  // then loads the transformed content via build_draft.loadTemplateRaw.
  function _strategyA_prebake(pkgString) {
    var stylesXml = _extractPkgPart(pkgString, "styles");
    var numberingXml = _extractPkgPart(pkgString, "numbering");
    if (!stylesXml) return { pkg: pkgString, log: { skipped: "no_styles" } };

    var styleNumId = {}, styleIlvl = {};
    var styleRe = /<w:style\b([^>]*)>([\s\S]*?)<\/w:style>/g, sm;
    while ((sm = styleRe.exec(stylesXml))) {
      if (sm[1].indexOf('w:customStyle="1"') === -1) continue;
      var idM = sm[1].match(/w:styleId="([^"]+)"/);
      if (!idM) continue;
      var pPr = sm[2].match(/<w:pPr>([\s\S]*?)<\/w:pPr>/);
      if (!pPr) continue;
      var numPr = pPr[1].match(/<w:numPr>([\s\S]*?)<\/w:numPr>/);
      if (!numPr) continue;
      var nidM = numPr[1].match(/<w:numId\s+w:val="(\d+)"/);
      if (!nidM || nidM[1] === "0") continue;
      styleNumId[idM[1]] = nidM[1];
      var ilvM = numPr[1].match(/<w:ilvl\s+w:val="(\d+)"/);
      if (ilvM) styleIlvl[idM[1]] = ilvM[1];
    }
    if (!Object.keys(styleNumId).length) return { pkg: pkgString, log: { skipped: "no_numbered_styles" } };

    // Reverse-lookup: ilvl from abstractNum's linked pStyle.
    var ilvlByStyle = {};
    if (numberingXml) {
      var seen = {};
      Object.keys(styleNumId).forEach(function (sid) {
        var nid = styleNumId[sid];
        if (seen[nid]) return;
        seen[nid] = true;
        var numBlock = numberingXml.match(new RegExp('<w:num\\s+w:numId="' + nid + '"[^>]*>([\\s\\S]*?)<\\/w:num>'));
        if (!numBlock) return;
        var absIdM = numBlock[1].match(/<w:abstractNumId\s+w:val="(\d+)"/);
        if (!absIdM) return;
        var absBlock = numberingXml.match(new RegExp('<w:abstractNum\\s+w:abstractNumId="' + absIdM[1] + '"[^>]*>([\\s\\S]*?)<\\/w:abstractNum>'));
        if (!absBlock) return;
        var lvlRe = /<w:lvl\b([^>]*)>([\s\S]*?)<\/w:lvl>/g, lm;
        while ((lm = lvlRe.exec(absBlock[1]))) {
          var ilvlM = lm[1].match(/w:ilvl="(\d+)"/);
          if (!ilvlM) continue;
          var linkedM = lm[2].match(/<w:pStyle\s+w:val="([^"]+)"\s*\/>/);
          if (linkedM) ilvlByStyle[linkedM[1]] = ilvlM[1];
        }
      });
    }

    var styleMap = {};
    Object.keys(styleNumId).forEach(function (sid) {
      styleMap[sid] = {
        numId: styleNumId[sid],
        ilvl: ilvlByStyle[sid] || styleIlvl[sid] || "0",
        ilvlSource: ilvlByStyle[sid] ? "abstractNum" : (styleIlvl[sid] ? "style_pPr" : "default"),
      };
    });

    var docPartRe = /(<pkg:part[^>]+name="\/word\/document\.xml"[^>]*>)([\s\S]*?)(<\/pkg:part>)/;
    var docMatch = pkgString.match(docPartRe);
    if (!docMatch) return { pkg: pkgString, log: { skipped: "no_document_part" } };
    var docOpen = docMatch[1], docXml = docMatch[2], docClose = docMatch[3];

    var bakedCount = 0, bakedByStyle = {};
    var newDocXml = docXml.replace(/<w:p\b([^>]*)>([\s\S]*?)<\/w:p>/g, function (m, pAttrs, pInner) {
      var pStyleM = pInner.match(/<w:pStyle\s+w:val="([^"]+)"\s*\/>/);
      if (!pStyleM) return m;
      var sn = styleMap[pStyleM[1]];
      if (!sn) return m;
      var pPrM = pInner.match(/<w:pPr>([\s\S]*?)<\/w:pPr>/);
      if (!pPrM) return m;
      var pPrI = pPrM[1];
      var existingNumPr = pPrI.match(/<w:numPr>([\s\S]*?)<\/w:numPr>/);
      if (existingNumPr && /<w:numId\s+w:val="\d+"\s*\/>/.test(existingNumPr[1])) return m;
      var correctNumPr = '<w:numPr><w:ilvl w:val="' + sn.ilvl + '"/><w:numId w:val="' + sn.numId + '"/></w:numPr>';
      var newPPrI = existingNumPr
        ? pPrI.replace(/<w:numPr>[\s\S]*?<\/w:numPr>/, function () { return correctNumPr; })
        : pPrI + correctNumPr;
      bakedCount++;
      bakedByStyle[pStyleM[1]] = (bakedByStyle[pStyleM[1]] || 0) + 1;
      var newPInner = pInner.replace(/<w:pPr>[\s\S]*?<\/w:pPr>/, function () { return '<w:pPr>' + newPPrI + '</w:pPr>'; });
      return '<w:p' + pAttrs + '>' + newPInner + '</w:p>';
    });

    var newDoc = docOpen + newDocXml + docClose;
    var newPkg = pkgString.replace(docPartRe, function () { return newDoc; });
    return {
      pkg: newPkg,
      log: { strategy: "A_prebake", styleMap: styleMap, bakedCount: bakedCount, bakedByStyle: bakedByStyle },
    };
  }

  // Strategy B — post-insert Word.js Style API repair. Sets bold/italic/jc
  // on each custom style based on source's expected values.
  function _strategyB_postApi(sourceStyleSpecs) {
    return eli.host.runRaw("trl:strategy_b", function (ctx) {
      var styles = ctx.document.getStyles();
      styles.load("items/nameLocal");
      return ctx.sync().then(function () {
        var byName = {};
        (styles.items || []).forEach(function (s) { try { byName[s.nameLocal] = s; } catch (_e) {} });
        var work = [];
        sourceStyleSpecs.forEach(function (spec) {
          var s = byName[spec.name];
          if (!s) return;
          s.load("font/bold, font/italic, font/size, paragraphFormat/alignment");
          work.push({ spec: spec, style: s });
        });
        return ctx.sync().then(function () {
          var ops = [];
          work.forEach(function (w) {
            var spec = w.spec, s = w.style, applied = [];
            try {
              if (spec.bold && s.font.bold !== true) { s.font.bold = true; applied.push("bold"); }
              if (spec.italic && s.font.italic !== true) { s.font.italic = true; applied.push("italic"); }
              if (spec.sz) {
                var pt = parseInt(spec.sz, 10) / 2;
                if (Math.abs((s.font.size || 0) - pt) > 0.5) { s.font.size = pt; applied.push("size:" + pt); }
              }
              if (spec.jc && Word && Word.Alignment) {
                var map = { left: Word.Alignment.left, right: Word.Alignment.right, center: Word.Alignment.centered, centered: Word.Alignment.centered, both: Word.Alignment.justified, justified: Word.Alignment.justified };
                var exp = map[spec.jc];
                if (exp && s.paragraphFormat.alignment !== exp) { s.paragraphFormat.alignment = exp; applied.push("align:" + spec.jc); }
              }
            } catch (_e) {}
            if (applied.length) ops.push({ name: spec.name, applied: applied });
          });
          return ctx.sync().then(function () { return { strategy: "B_postApi", ops: ops, matched: work.length, total: sourceStyleSpecs.length }; });
        });
      });
    });
  }

  // ─── tile / load orchestration ──────────────────────────────────────
  function _loadSelected(opts) {
    opts = opts || {};
    if (!_state.selectedId) { _toast("Pick a template first", "err"); return; }
    return _fetchTemplate(_state.selectedId).then(function (fetched) {
      _state.selectedRow = fetched.row;
      // Parse the JSON envelope; the body field holds the pkg:package string.
      var parsed = null;
      try { parsed = JSON.parse(fetched.contentString); } catch (_e) {}
      _state.sourcePkg = (parsed && parsed.body) || fetched.contentString;
      _state.sourceParts = _parseAllParts(_state.sourcePkg);

      var contentToLoad = fetched.contentString;
      var transformLog = null;
      if (opts.strategyA) {
        var aResult = _strategyA_prebake(_state.sourcePkg);
        transformLog = aResult.log;
        if (parsed) {
          parsed.body = aResult.pkg;
          contentToLoad = JSON.stringify(parsed);
        } else {
          contentToLoad = aResult.pkg;
        }
      }

      if (!eli.dispatch) { _toast("eli.dispatch missing", "err"); return; }
      var loadP = eli.dispatch("build_draft", "loadTemplateRaw", contentToLoad);
      if (!loadP || typeof loadP.then !== "function") {
        _toast("build_draft.loadTemplateRaw returned non-promise — is build_draft installed?", "err");
        return;
      }
      return loadP.then(function () {
        _toast("Loaded" + (opts.strategyA ? " (Strategy A pre-bake)" : ""), "ok");
        if (transformLog) try { console.log("[trl] Strategy A:", transformLog); } catch (_) {}
        return _refreshTarget();
      });
    }).catch(function (e) {
      _toast("Load failed: " + (e && e.message || e), "err");
      try { console.error("[trl] load error:", e); } catch (_) {}
    });
  }

  function _refreshTarget() {
    return _fetchTargetPkg().then(function (pkg) {
      _state.targetPkg = pkg;
      _state.targetParts = _parseAllParts(pkg);
      _render();
    }).catch(function (e) {
      _toast("Target fetch failed: " + (e && e.message || e), "err");
    });
  }

  function _runStrategyB() {
    if (!_state.sourceParts) { _toast("Load a template first", "err"); return; }
    var specs = _inspectCustomStyles(_state.sourceParts.styles);
    return _strategyB_postApi(specs).then(function (result) {
      _toast("Strategy B done: " + result.ops.length + " styles touched", "ok");
      try { console.log("[trl] Strategy B:", result); } catch (_) {}
      return _refreshTarget();
    }).catch(function (e) {
      _toast("Strategy B failed: " + (e && e.message || e), "err");
    });
  }

  // ─── UI ──────────────────────────────────────────────────────────────
  function _renderRow(label, value, opts) {
    opts = opts || {};
    var color = opts.warn ? "#b91c1c" : (opts.ok ? "#047857" : "#0f172a");
    return '<div style="display:flex;justify-content:space-between;gap:8px;padding:3px 0;font:500 12px/1.4 ui-monospace,Menlo,monospace;border-bottom:1px solid #f1f5f9;">' +
      '<span style="color:#64748b;">' + _esc(label) + '</span>' +
      '<span style="color:' + color + ';text-align:right;">' + _esc(value) + '</span>' +
      '</div>';
  }

  function _renderStyleTable(specs) {
    if (!specs.length) return '<div style="color:#94a3b8;font-style:italic;">(no custom styles)</div>';
    var rows = specs.map(function (s) {
      var nidColor = (s.numId === "0") ? "#b91c1c" : (s.numId ? "#047857" : "#94a3b8");
      return '<tr>' +
        '<td style="padding:4px 8px;font-weight:600;">' + _esc(s.styleId) + '</td>' +
        '<td style="padding:4px 8px;color:#475569;">' + _esc(s.name) + '</td>' +
        '<td style="padding:4px 8px;color:' + nidColor + ';font-weight:600;">' + _esc(s.numId == null ? "—" : s.numId) + '</td>' +
        '<td style="padding:4px 8px;color:#475569;">' + _esc(s.ilvl == null ? "—" : s.ilvl) + '</td>' +
        '<td style="padding:4px 8px;color:' + (s.bold ? "#047857" : "#cbd5e1") + ';">' + (s.bold ? "✓" : "—") + '</td>' +
        '<td style="padding:4px 8px;color:' + (s.italic ? "#047857" : "#cbd5e1") + ';">' + (s.italic ? "✓" : "—") + '</td>' +
        '<td style="padding:4px 8px;color:' + (s.jc ? "#047857" : "#cbd5e1") + ';">' + _esc(s.jc || "—") + '</td>' +
        '<td style="padding:4px 8px;color:#475569;">' + _esc(s.sz || "—") + '</td>' +
      '</tr>';
    }).join("");
    return '<table style="width:100%;border-collapse:collapse;font:500 11.5px/1.4 ui-monospace,Menlo,monospace;">' +
      '<thead><tr style="background:#f8fafc;color:#64748b;font-size:10.5px;text-transform:uppercase;">' +
      '<th style="padding:6px 8px;text-align:left;">styleId</th>' +
      '<th style="padding:6px 8px;text-align:left;">name</th>' +
      '<th style="padding:6px 8px;text-align:left;">numId</th>' +
      '<th style="padding:6px 8px;text-align:left;">ilvl</th>' +
      '<th style="padding:6px 8px;text-align:left;">B</th>' +
      '<th style="padding:6px 8px;text-align:left;">I</th>' +
      '<th style="padding:6px 8px;text-align:left;">jc</th>' +
      '<th style="padding:6px 8px;text-align:left;">sz</th>' +
      '</tr></thead><tbody>' + rows + '</tbody></table>';
  }

  function _renderNumTable(nums) {
    if (!nums.length) return '<div style="color:#94a3b8;font-style:italic;">(no numbering)</div>';
    var rows = nums.slice(0, 40).map(function (n) {
      var lvlSummary = n.levels.slice(0, 4).map(function (l) {
        var linked = l.linkedStyle ? ' →' + l.linkedStyle : "";
        return "L" + l.ilvl + ":" + (l.lvlText || "—") + linked;
      }).join(" | ");
      return '<tr>' +
        '<td style="padding:4px 8px;font-weight:600;">' + _esc(n.numId) + '</td>' +
        '<td style="padding:4px 8px;color:#475569;">' + _esc(n.abstractNumId == null ? "—" : n.abstractNumId) + '</td>' +
        '<td style="padding:4px 8px;color:#475569;font-size:10.5px;">' + _esc(lvlSummary) + '</td>' +
      '</tr>';
    }).join("");
    return '<table style="width:100%;border-collapse:collapse;font:500 11.5px/1.4 ui-monospace,Menlo,monospace;">' +
      '<thead><tr style="background:#f8fafc;color:#64748b;font-size:10.5px;text-transform:uppercase;">' +
      '<th style="padding:6px 8px;text-align:left;">numId</th>' +
      '<th style="padding:6px 8px;text-align:left;">absId</th>' +
      '<th style="padding:6px 8px;text-align:left;">levels (lvlText →linkedStyle)</th>' +
      '</tr></thead><tbody>' + rows + '</tbody></table>';
  }

  function _renderParaTable(paras) {
    if (!paras.length) return '<div style="color:#94a3b8;font-style:italic;">(no Colgate-styled paragraphs)</div>';
    var rows = paras.map(function (p) {
      var nidColor = (p.numId === "0") ? "#b91c1c" : (p.numId ? "#047857" : "#cbd5e1");
      return '<tr>' +
        '<td style="padding:3px 8px;color:#94a3b8;font-size:10.5px;">#' + p.index + '</td>' +
        '<td style="padding:3px 8px;font-weight:600;">' + _esc(p.style) + '</td>' +
        '<td style="padding:3px 8px;color:' + nidColor + ';">' + _esc(p.numId == null ? "—" : p.numId) + '</td>' +
        '<td style="padding:3px 8px;color:#475569;">' + _esc(p.ilvl == null ? "—" : p.ilvl) + '</td>' +
        '<td style="padding:3px 8px;color:#475569;">' + _esc(p.text) + '</td>' +
      '</tr>';
    }).join("");
    return '<table style="width:100%;border-collapse:collapse;font:500 11.5px/1.4 ui-monospace,Menlo,monospace;">' +
      '<thead><tr style="background:#f8fafc;color:#64748b;font-size:10.5px;text-transform:uppercase;">' +
      '<th style="padding:6px 8px;text-align:left;">#</th>' +
      '<th style="padding:6px 8px;text-align:left;">style</th>' +
      '<th style="padding:6px 8px;text-align:left;">numId</th>' +
      '<th style="padding:6px 8px;text-align:left;">ilvl</th>' +
      '<th style="padding:6px 8px;text-align:left;">text</th>' +
      '</tr></thead><tbody>' + rows + '</tbody></table>';
  }

  function _renderSection(title, html) {
    return '<div style="background:#fff;border:1px solid #e2e8f0;border-radius:8px;padding:14px 16px;margin-bottom:12px;">' +
      '<div style="font:700 12.5px/1.2 \'Inter\',sans-serif;color:#0f172a;margin-bottom:10px;text-transform:uppercase;letter-spacing:0.4px;">' + _esc(title) + '</div>' +
      html +
      '</div>';
  }

  function _renderInspector(label, parts) {
    if (!parts) return _renderSection(label, '<div style="color:#94a3b8;font-style:italic;">(not loaded)</div>');
    var styles = _inspectCustomStyles(parts.styles);
    var nums = _inspectNumbering(parts.numbering);
    var paras = _inspectParagraphs(parts.document, 30);
    return _renderSection(label,
      '<div style="font:600 11px/1 \'Inter\',sans-serif;color:#64748b;margin:0 0 6px;letter-spacing:0.3px;">CUSTOM STYLES</div>' +
      _renderStyleTable(styles) +
      '<div style="font:600 11px/1 \'Inter\',sans-serif;color:#64748b;margin:14px 0 6px;letter-spacing:0.3px;">NUMBERING DEFS</div>' +
      _renderNumTable(nums) +
      '<div style="font:600 11px/1 \'Inter\',sans-serif;color:#64748b;margin:14px 0 6px;letter-spacing:0.3px;">COLGATE PARAGRAPHS (first 30)</div>' +
      _renderParaTable(paras)
    );
  }

  function _render() {
    var mount = document.getElementById("_eli3_dashboard_root");
    if (!mount) { _toast("Dashboard root missing", "err"); return; }
    mount.innerHTML = "";
    var root = document.createElement("div");
    root.style.cssText = "background:#f1f5f9;min-height:100%;padding:0;font:500 13px/1.45 'Inter','Segoe UI',sans-serif;color:#0f172a;";

    // Header bar.
    var headerHtml =
      '<div style="background:linear-gradient(180deg,#fff,#f8fafc);border-bottom:1px solid #e2e8f0;padding:14px 20px;display:flex;align-items:center;gap:12px;position:sticky;top:0;z-index:5;">' +
        '<button data-act="back" title="Back" style="border:1px solid #e2e8f0;background:#fff;border-radius:6px;padding:4px 10px;cursor:pointer;font-size:14px;color:#475569;">←</button>' +
        '<div style="font:700 15px/1 \'Inter\',sans-serif;color:#0f172a;">🔬 Template Repair Lab</div>' +
        '<div style="margin-left:auto;font-size:11px;color:#64748b;">admin-only • iterates on style/numbering repair</div>' +
      '</div>';

    // Controls.
    var selectedLabel = _state.selectedRow
      ? _esc(_state.selectedRow.name || _state.selectedId)
      : '<span style="color:#94a3b8;">(none selected)</span>';
    var controlsHtml =
      '<div style="padding:18px 24px;max-width:1100px;margin:0 auto;">' +
        '<div style="background:#fff;border:1px solid #e2e8f0;border-radius:10px;padding:16px 18px;margin-bottom:14px;">' +
          '<div style="display:flex;gap:10px;align-items:center;margin-bottom:10px;">' +
            '<button data-act="pick" style="border:1px solid #cbd5e1;background:#fff;color:#0f172a;border-radius:6px;padding:8px 14px;cursor:pointer;font:600 12.5px/1 \'Inter\',sans-serif;">📂 Pick template</button>' +
            '<div style="flex:1;font:500 12.5px/1.4;color:#475569;">' + selectedLabel + '</div>' +
          '</div>' +
          '<div style="display:flex;gap:8px;flex-wrap:wrap;">' +
            '<button data-act="load" style="border:1px solid #1d4ed8;background:linear-gradient(180deg,#3b82f6,#2563eb);color:#fff;border-radius:6px;padding:8px 14px;cursor:pointer;font:600 12.5px/1 \'Inter\',sans-serif;" ' +
              (!_state.selectedId ? "disabled" : "") + '>▶ Load raw (no repair)</button>' +
            '<button data-act="load_a" style="border:1px solid #047857;background:linear-gradient(180deg,#10b981,#059669);color:#fff;border-radius:6px;padding:8px 14px;cursor:pointer;font:600 12.5px/1 \'Inter\',sans-serif;" ' +
              (!_state.selectedId ? "disabled" : "") + '>⚙ Load + Strategy A (pre-bake numPr)</button>' +
            '<button data-act="run_b" style="border:1px solid #92400e;background:linear-gradient(180deg,#fbbf24,#d97706);color:#fff;border-radius:6px;padding:8px 14px;cursor:pointer;font:600 12.5px/1 \'Inter\',sans-serif;" ' +
              (!_state.targetPkg ? "disabled" : "") + '>🔧 Strategy B (post-load Style API repair)</button>' +
            '<button data-act="refresh" style="border:1px solid #cbd5e1;background:#fff;color:#0f172a;border-radius:6px;padding:8px 14px;cursor:pointer;font:600 12.5px/1 \'Inter\',sans-serif;" ' +
              (!_state.selectedId ? "disabled" : "") + '>↻ Re-inspect target</button>' +
          '</div>' +
          '<div style="margin-top:10px;font-size:11px;color:#64748b;line-height:1.5;">' +
            '<b>Load raw</b>: calls build_draft.loadTemplateRaw — no transformation. Baseline.<br>' +
            '<b>Strategy A</b>: pre-bake inline numPr on paragraphs (with abstractNum lvl→pStyle reverse-lookup) BEFORE insertOoxml.<br>' +
            '<b>Strategy B</b>: post-load Word.js Style API to set bold/italic/size/jc on each custom style.' +
          '</div>' +
        '</div>' +
        _renderInspector("SOURCE pkg (decompressed IDB row)", _state.sourceParts) +
        _renderInspector("TARGET pkg (live Word body OOXML)", _state.targetParts) +
      '</div>';

    root.innerHTML = headerHtml + controlsHtml;
    mount.appendChild(root);

    root.querySelector("[data-act='back']").onclick = function () {
      if (eli.dashboard && eli.dashboard.goHome) eli.dashboard.goHome();
    };
    root.querySelector("[data-act='pick']").onclick = _openPicker;
    var btnLoad = root.querySelector("[data-act='load']");
    if (btnLoad) btnLoad.onclick = function () { _loadSelected({}); };
    var btnLoadA = root.querySelector("[data-act='load_a']");
    if (btnLoadA) btnLoadA.onclick = function () { _loadSelected({ strategyA: true }); };
    var btnB = root.querySelector("[data-act='run_b']");
    if (btnB) btnB.onclick = _runStrategyB;
    var btnRefresh = root.querySelector("[data-act='refresh']");
    if (btnRefresh) btnRefresh.onclick = _refreshTarget;
  }

  // ─── template picker dialog ──────────────────────────────────────────
  function _openPicker() {
    _listTemplates().then(function (rows) {
      if (!rows.length) { _toast("No templates in bd_templates", "err"); return; }
      var rowsHtml = rows.map(function (r) {
        var when = r.modifiedAt ? new Date(r.modifiedAt).toLocaleString() : "—";
        var sizeKB = r.content
          ? ((typeof r.content === "string" ? r.content.length : r.content.byteLength || 0) / 1024).toFixed(1)
          : "?";
        return '<div data-id="' + _esc(r.id) + '" style="padding:10px 14px;border-bottom:1px solid #f1f5f9;cursor:pointer;display:flex;justify-content:space-between;gap:14px;" onmouseover="this.style.background=\'#f8fafc\'" onmouseout="this.style.background=\'\'">' +
          '<div style="min-width:0;">' +
            '<div style="font:600 13px/1.3;color:#0f172a;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">' + _esc(r.name || r.id) + '</div>' +
            '<div style="font-size:11px;color:#94a3b8;margin-top:2px;">' + _esc(r.id) + (r._z ? ' • compressed' : '') + '</div>' +
          '</div>' +
          '<div style="font-size:11px;color:#64748b;text-align:right;flex-shrink:0;">' +
            '<div>' + sizeKB + ' KB</div>' +
            '<div style="margin-top:2px;">' + _esc(when) + '</div>' +
          '</div>' +
        '</div>';
      }).join("");
      if (typeof showEliDialog !== "function") { _toast("showEliDialog missing", "err"); return; }
      showEliDialog({
        title: "Pick a template",
        sizeKey: "lg",
        html: '<div style="max-height:480px;overflow:auto;border:1px solid #e2e8f0;border-radius:8px;background:#fff;">' + rowsHtml + '</div>',
        onMount: function (root) {
          root.querySelectorAll("[data-id]").forEach(function (el) {
            el.onclick = function () {
              _state.selectedId = el.getAttribute("data-id");
              _state.selectedRow = rows.filter(function (r) { return r.id === _state.selectedId; })[0] || null;
              _state.sourcePkg = null;
              _state.sourceParts = null;
              _state.targetPkg = null;
              _state.targetParts = null;
              if (typeof closeDialog === "function") closeDialog();
              else if (window.eli && window.eli.ui && typeof window.eli.ui.closeAll === "function") window.eli.ui.closeAll();
              _render();
            };
          });
        },
      });
    }).catch(function (e) {
      _toast("List failed: " + (e && e.message || e), "err");
    });
  }

  eli.register({
    tile: { app_template_repair_lab: _render },
    template_repair_lab: { open: _render },
  });

  eli.log.event("tool", "template_repair_lab_initialized", {});
}
